// Distributed swap: sell 500 USDC for SOL (minimum 4.2 SOL) across 4 venues with price limit
// sauce simulate sauce/distributed_swap.sauce.ts --args "500000000" "116000000000000000" "4200000000" "116000000000000000" --accounts '{"authority":"pot","source":"pot:USDC","output":"pot:WSOL","recipient":"pot:WSOL","refund":"pot:USDC","payMint":"mint:USDC","buyMint":"mint:WSOL","tokenProgram":"program:USDC"}' --assume-balance "USDC:500" "WSOL:0"
// budget: u64, max USDC to spend in base units (6 decimals; 500000000 = 500 USDC)
