import { Kitchen } from '@sauce/svm';
import { token } from '@sauce/token';

export async function main(usdcAmount: u64): Promise<{ success: boolean; solReceived: u64 }> {
  const kitchens = await Kitchen.all();

  // Use the first available Kitchen (usually the only one on Solana)
  const kitchen = kitchens[0];

  // Define price limit: never below 0.0084 SOL per USDC
  // This means for 500 USDC, we want at least 500 * 0.0084 = 4.2 SOL
  // With 9 decimals: 4.2 * 1e9 = 4200000000 lamports
  const minSolOut = (usdcAmount * 84n) / 10000n; // 0.0084 * usdcAmount

  // Perform distributed swap across venues
  // Each venue route handles a portion of the swap with the price limit
  let totalSolReceived = 0n;

  // Route 1: Jupiter (comprehensive aggregator, supports price limits)
  try {
    const jupiterOut = await kitchen.swap(
      token('USDC'),
      token('SOL'),
      usdcAmount / 4n,  // 25% through Jupiter
      minSolOut / 4n,   // proportional minimum
      'jupiter'
    );
    totalSolReceived += jupiterOut;
  } catch (e) {
    // Continue if one route fails
  }

  // Route 2: Orca (DEX with good USDC-SOL liquidity)
  try {
    const orcaOut = await kitchen.swap(
      token('USDC'),
      token('SOL'),
      usdcAmount / 4n,  // 25% through Orca
      minSolOut / 4n,
      'orca'
    );
    totalSolReceived += orcaOut;
  } catch (e) {
    // Continue if one route fails
  }

  // Route 3: Raydium (Solana's liquidity provider)
  try {
    const raydiumOut = await kitchen.swap(
      token('USDC'),
      token('SOL'),
      usdcAmount / 4n,  // 25% through Raydium
      minSolOut / 4n,
      'raydium'
    );
    totalSolReceived += raydiumOut;
  } catch (e) {
    // Continue if one route fails
  }

  // Route 4: Marinade (liquid staking, supports SOL swaps)
  try {
    const marinadeOut = await kitchen.swap(
      token('USDC'),
      token('SOL'),
      usdcAmount / 4n,  // 25% through Marinade
      minSolOut / 4n,
      'marinade'
    );
    totalSolReceived += marinadeOut;
  } catch (e) {
    // Continue if one route fails
  }

  return {
    success: totalSolReceived >= minSolOut,
    solReceived: totalSolReceived
  };
}

